template.query:
mutation UpdateNodeContent($id: ID!, $content: String!) {
  updateNode(
    id: $id
    input: {
      content: $content
    }
  ) {
    success
    node {
      id
      content
      table {
        id
        identifier
      }
      attributes {
        id
        value
        attribute {
          identifier
          name
        }
      }
      attributeCount
      relationCount
      createdAt
      updatedAt
    }
    errors {
      message
      code
      field
    }
  }
}
